/**
 * canteens.ts – hard-coded "fake" database for the mensa app.
 *
 * Generated from mensa-db.json (ETH + UZH, 22 mensas, 901 dishes,
 * 2026-09-28 to 2026-10-09). Do not edit by hand; rebuild with
 * scripts/export-canteens-ts.mjs.
 *
 * REAL      mensas (address, contacts, hours, photo links), dishes, prices,
 *           allergens, origin, nutrition (ETH per 100 g, UZH per serving)
 * ESTIMATED ETH per-portion nutrition (nutrition.perPortion.estimated === true)
 * SYNTHETIC crowd / fullness series (15 min steps) and mensa star ratings
 *
 * Usage:
 *   import { DB, MENSAS, MEALS, CROWD, CANTEENS } from '../data/canteens';
 *
 * CANTEENS / MENU_DATE / LIVE_DATA (bottom) are the shapes the current pages use.
 * New features should read DB / MENSAS / MEALS / CROWD directly.
 */

import { pickSampleMenuDate } from './menuDate.ts';

// ───────── types of the database ─────────

export type Weekday = 'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat' | 'sun';
export type Service = 'lunch' | 'dinner';
export type DietTag = 'vegan' | 'vegetarian' | 'meat' | 'fish';
export type MealKind = 'main' | 'buffet' | 'dessert' | 'drink';
export type CampusId = 'zentrum' | 'hoenggerberg' | 'irchel' | 'oerlikon' | 'basel' | 'toni-areal' | 'europaallee';
export type Institution = 'ETH' | 'UZH' | 'PHZH' | 'ZHAW';
/** Canonical EU allergen ids. */
export type AllergenId =
  | 'gluten' | 'crustaceans' | 'eggs' | 'fish' | 'peanuts' | 'soy' | 'milk' | 'nuts'
  | 'celery' | 'mustard' | 'sesame' | 'sulphites' | 'lupin' | 'molluscs';

export interface Campus {
  id: CampusId;
  name: string;
  city: string;
  institutions: Institution[];
  coordinates: { lat: number; lng: number };
  note?: string;
}

export interface ServiceHours { service: Service; open: string; close: string }
export interface BuildingHours { open: string; close: string }

export interface Picture {
  /** mensa = photo of the place, stock = generic food photo of the operator, dish = a dish photo */
  kind: 'mensa' | 'stock' | 'dish';
  url: string;
  caption?: string;
  source: string;
}

export interface Mensa {
  id: string;
  name: string;
  institution: Institution;
  campusId: CampusId;
  address: { street: string; postalCode: string | null; city: string; building: string | null };
  coordinates: { lat: number; lng: number; source: string } | null;
  contact: { phone: string | null; email: string | null; website: string | null };
  operator: string | null;
  operatorUrl: string | null;
  paymentOptions: string[];
  features: string[];
  description: string | null;
  hasMenu: boolean;
  temporarilyClosed: boolean;
  /** Meal service windows per weekday (empty array = no service). */
  openingHours: Record<Weekday, ServiceHours[]>;
  /** Whole building / counter open times per weekday. */
  buildingHours: Record<Weekday, BuildingHours[]>;
  /** Raw hours text from the operator page (UZH only). */
  openingHoursText?: string | null;
  /** Opening-hours provenance, when supplied by the source record. */
  hoursSource?: string;
  closures: Array<{ from: string; to: string; note: string }>;
  pictures: Picture[];
  source: { provider: string; facilityId?: number; url: string | null; menuUrls?: string[] };
  /** SYNTHETIC. */
  rating: { synthetic: true; average: number; count: number };
}

export interface NutritionValues {
  energyKj: number | null;
  kcal: number | null;
  proteinG: number | null;
  fatG: number | null;
  saturatedFatG: number | null;
  carbsG: number | null;
  sugarG: number | null;
  saltG: number | null;
  fiberG: number | null;
}

export interface PortionNutrition {
  portionWeightG: number | null;
  portionWeightEstimated: boolean;
  /** true for ETH dishes: derived from per-100 g values and an assumed portion weight. */
  estimated: boolean;
  kcal: number | null;
  proteinG: number | null;
  fatG: number | null;
  saturatedFatG: number | null;
  carbsG: number | null;
  sugarG: number | null;
  saltG: number | null;
  fiberG: number | null;
}

export interface Meal {
  /** e.g. "polyterrasse.2026-10-06.lunch.2" */
  id: string;
  mensaId: string;
  /** YYYY-MM-DD */
  date: string;
  weekday: Weekday;
  service: Service;
  /** Counter / line name as published (STREET, GARDEN, garden, Menu 2 …). */
  line: string;
  kind: MealKind;
  title: string;
  /** German title (ETH has both languages, UZH is German only). */
  titleDe: string | null;
  components: string[];
  dietTag: DietTag;
  /** CHF. null = the source lists no price (or 0.00). */
  price: { student: number | null; staff: number | null; external: number | null };
  priceNote?: string | null;
  /** "serving", or "100g" for buffet items sold by weight. */
  priceUnit: string;
  allergens: AllergenId[];
  origin: string | null;
  originDetail: {
    meat: Array<{ type: string; countries: string[] }>;
    fish: Array<{ method: string; countries: string[] }>;
  } | null;
  /** null = the kitchen publishes no nutrition for this dish. */
  nutrition: {
    basis: 'per100g' | 'perPortion';
    per100g: NutritionValues;
    perPortion: PortionNutrition | null;
    suspect?: boolean;
    suspectReason?: string;
  } | null;
  /** ETH only: ECO Score letter grade, e.g. "C+". */
  ecoScore: string | null;
  /** UZH only: climate impact rating from ZFV. */
  climateImpact: 'LOW' | 'MEDIUM' | 'HIGH' | null;
  imageUrl: string | null;
  source: { provider: string; facilityId?: number; lineId?: number; detailUrl?: string };
  /** Language of title / components. */
  language: 'en' | 'de';
}

/** One day of SYNTHETIC fullness readings in 15 minute steps. */
export interface CrowdDay {
  /** First slot, HH:MM. Slot i starts at start + 15 min * i. */
  start: string;
  intervalMinutes: 15;
  /** Fullness 0-100. */
  pct: number[];
  /** 1 Empty, 2 Quiet, 3 Some queue, 4 Busy, 5 Packed (null when closed). */
  level: Array<number | null>;
  /** Fake number of user reports behind each slot. */
  reports: number[];
}

export interface CrowdSeries {
  synthetic: true;
  sufficientData: boolean;
  /** Keyed by YYYY-MM-DD. */
  days: Record<string, CrowdDay>;
  /** Average pct per weekday, keyed by HH:MM. */
  typicalByWeekday: Partial<Record<Weekday, { intervalMinutes: 15; basedOnDays: number; pct: Record<string, number> }>>;
}

export interface MensaDb {
  meta: {
    name: string;
    generatedAt: string;
    dateRange: { from: string; to: string; note: string };
    timezone: string;
    currency: string;
    sources: Array<{ id: string; url: string; what: string }>;
    dataQuality: { real: string[]; estimated: string[]; synthetic: string[]; notes: string[] };
    stats: Record<string, unknown>;
  };
  campuses: Campus[];
  mensas: Mensa[];
  meals: Meal[];
  crowd: Record<string, CrowdSeries>;
}

