for (const c of ADDITIONAL_CAMPUSES) {
  if (!DB.campuses.some(existing => existing.id === c.id)) {
    DB.campuses.push(c);
  }
}
for (const m of ADDITIONAL_MENSAS) {
  if (!DB.mensas.some(existing => existing.id === m.id)) {
    DB.mensas.push(m);
  }
}

export const CAMPUSES: Campus[] = DB.campuses;
export const MENSAS: Mensa[] = DB.mensas;
export const MEALS: Meal[] = DB.meals;
export const CROWD: Record<string, CrowdSeries> = DB.crowd;

// ───────── helpers ─────────

export const getMensa = (id: string): Mensa | undefined => MENSAS.find((m) => m.id === id);

/** Dishes of one mensa and day, lunch first. */
export const mealsOf = (mensaId: string, date: string, service?: Service): Meal[] =>
  MEALS.filter((m) => m.mensaId === mensaId && m.date === date && (!service || m.service === service)).sort(
    (x, y) => Number(x.service === 'dinner') - Number(y.service === 'dinner'),
  );

/** Crowd level 1-5 from a 0-100 value (same thresholds as the app). */
export const levelFromPct = (p: number): 1 | 2 | 3 | 4 | 5 => (p < 20 ? 1 : p < 40 ? 2 : p < 60 ? 3 : p < 80 ? 4 : 5);

/** "6.10", or "–" when the source publishes no price. Use as `CHF {formatPrice(x)}`. */
export const formatPrice = (value: number | null | undefined): string => (value === null || value === undefined ? '–' : value.toFixed(2));

// ───────── UI shape used by the pages ─────────

export type DietaryType = 'vegan' | 'vegetarian' | 'meat';
export type OccupancyLevel = 'low' | 'medium' | 'high';

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  /** CHF, null = no price published. */
  priceStudent: number | null;
  priceWorker: number | null;
  priceExternal: number | null;
  /** Fish dishes are listed as 'meat' here; use MEALS[..].dietTag for the real value. */
  dietary: DietaryType;
  allergens?: string[];
  category: 'Daily Special' | 'Classic' | 'Side';
  // Extra fields the DB provides (not used by the pages yet):
  service?: Service;
  imageUrl?: string | null;
  kcal?: number | null;
  proteinG?: number | null;
}

export interface Canteen {
  id: string;
  name: string;
  /** Display label, e.g. "ETH Zentrum" or "UZH Zentrum". */
  campus: string;
  /** Filter key. "Zentrum" covers ETH and UZH. */
  campusId: CampusId;
  location: string;
  isOpen: boolean;
  hours: string;
  occupancy: OccupancyLevel;
  rating: number;
  imageUrl: string;
  menu: MenuItem[];
}

const WEEKDAYS: Weekday[] = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const ALLERGEN_LABEL: Record<AllergenId, string> = {
  gluten: 'Gluten', crustaceans: 'Crustaceans', eggs: 'Eggs', fish: 'Fish', peanuts: 'Peanuts', soy: 'Soy', milk: 'Milk',
  nuts: 'Tree nuts', celery: 'Celery', mustard: 'Mustard', sesame: 'Sesame', sulphites: 'Sulphites', lupin: 'Lupin', molluscs: 'Molluscs',
};

const toMin = (s: string) => Number(s.slice(0, 2)) * 60 + Number(s.slice(3, 5));
const hhmm = (min: number) => `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;

/** Current weekday, date and minutes since midnight in Zürich. */
function zurichNow(): { weekday: Weekday; date: string; minutes: number } {
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Zurich', weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? '';
  const weekday = WEEKDAYS.find((w) => w === get('weekday').toLowerCase().slice(0, 3)) ?? 'mon';
  return { weekday, date: `${get('year')}-${get('month')}-${get('day')}`, minutes: (Number(get('hour')) % 24) * 60 + Number(get('minute')) };
}

/**
 * The day whose menu the pages show: today on weekdays, the latest Monday of the data on Saturday and
 * Sunday; if the database has no such day, the most recent day before today, otherwise its first day.
 * (The database is a hard-coded snapshot, 2026-09-28 to 2026-10-09.) Rule: ./menuDate.ts
 */
function pickMenuDate(): string {
  return pickSampleMenuDate(MEALS.map((m) => m.date), zurichNow().date);
}
export const MENU_DATE: string = pickMenuDate();

/** Windows (minutes since midnight) in which a mensa counts as open: meal services, else building hours. */
function windowsOf(m: Mensa): Record<Weekday, Array<[number, number]>> {
  const out = {} as Record<Weekday, Array<[number, number]>>;
  for (const d of WEEKDAYS) {
    const src = (m.openingHours && m.openingHours[d]?.length) ? m.openingHours[d] : ((m.buildingHours && m.buildingHours[d]?.length) ? m.buildingHours[d] : []);
    out[d] = src.map((w) => [toMin(w.open), toMin(w.close)]);
  }
  return out;
}

/** Typical crowd (0-100) per weekday as { start minute, one value per 15 min }. */
function crowdOf(id: string): LiveInfo['crowd'] {
  const out: LiveInfo['crowd'] = {};
  for (const d of WEEKDAYS) {
    const t = CROWD[id]?.typicalByWeekday[d];
    if (!t) continue;
    const keys = Object.keys(t.pct);
    if (keys.length) out[d] = { start: toMin(keys[0] as string), pct: keys.map((k) => t.pct[k] as number) };
  }
  return out;
}

const occupancyOf = (pct: number): OccupancyLevel => (pct < 40 ? 'low' : pct < 70 ? 'medium' : 'high');

/**
 * Everything the browser needs to refresh "open now", opening hours and the
 * crowd level after the page was built (see src/scripts/live-status.ts).
 */
export interface LiveInfo {
  temporarilyClosed: boolean;
  windows: Record<Weekday, Array<[number, number]>>;
  crowd: Partial<Record<Weekday, { start: number; pct: number[] }>>;
}

export const LIVE_DATA: Record<string, LiveInfo> = Object.fromEntries(
  MENSAS.map((m) => [m.id, { temporarilyClosed: m.temporarilyClosed, windows: windowsOf(m), crowd: crowdOf(m.id) } satisfies LiveInfo]),
);

function toCanteen(m: Mensa): Canteen {
  const now = zurichNow();
  const live = LIVE_DATA[m.id] as LiveInfo;
  const windows = live.windows[now.weekday];
  const isOpen = !m.temporarilyClosed && windows.some(([a, b]) => now.minutes >= a && now.minutes < b);
  const hours = m.temporarilyClosed ? 'Temporarily closed' : windows.length ? windows.map(([a, b]) => `${hhmm(a)} - ${hhmm(b)}`).join(' · ') : 'Closed today';

  const crowd = live.crowd[now.weekday];
  const idx = crowd ? Math.floor((now.minutes - crowd.start) / 15) : -1;
  const pct = crowd && idx >= 0 ? (crowd.pct[idx] ?? 0) : 0;

  const menu: MenuItem[] = mealsOf(m.id, MENU_DATE)
    .sort((a, b) => Number(a.kind !== 'main') - Number(b.kind !== 'main'))
    .map((meal, i) => ({
      id: meal.id,
      name: meal.title,
      description: meal.components.join(', '),
      priceStudent: meal.price.student,
      priceWorker: meal.price.staff,
      priceExternal: meal.price.external,
      dietary: meal.dietTag === 'fish' ? 'meat' : meal.dietTag,
      allergens: meal.allergens.map((a) => ALLERGEN_LABEL[a]),
      category: meal.kind !== 'main' ? 'Side' : i === 0 ? 'Daily Special' : 'Classic',
      service: meal.service,
      imageUrl: meal.imageUrl,
      kcal: meal.nutrition?.perPortion?.kcal ?? null,
      proteinG: meal.nutrition?.perPortion?.proteinG ?? null,
    }));

  const photo = m.pictures.find((p) => p.kind === 'mensa') ?? m.pictures.find((p) => p.kind === 'stock') ?? m.pictures[0];
  return {
    id: m.id,
    name: m.name,
    campus: `${m.institution} ${CAMPUSES.find((c) => c.id === m.campusId)?.name ?? ''}` as Canteen['campus'],
    campusId: m.campusId,
    location: m.address.building ?? m.address.street,
    isOpen,
    hours,
    occupancy: occupancyOf(pct),
    rating: m.rating.average,
    imageUrl: photo?.url ?? '',
    menu,
  };
}

export const CANTEENS: Canteen[] = MENSAS.map(toCanteen);
